{
  "strokeMm": 40.0,
  "crankRadiusMm": 20,
  "rodLengthMm": 100,
  "valveDrive": "prescribed",
  "valveDriveReason": "simulate_motion 只接受曲柄定速驱动 + 正弦 prescribed 振荡器两种驱动；规格要求简化滑阀+阀杆，故滑阀用与曲柄同周期(periodSec=1s 对应曲柄 1 圈/s)、沿缸轴向往复 ±6mm 的振荡器驱动，与曲柄保持固定相位关系（r021 实测 travel 12.000mm）。偏心轮+阀杆的 mechanism 链在工具上原则上可建（再多两根连杆两个转动副），但规格明确为简化阀，且振荡器不会像齿条近似那样漂移相位，演示目的下 prescribed 是如实且可复核的选择。",
  "fluidStructureCoupling": "none",
  "couplingReason": "simulate_fluid 是固体边界全程固定的 MPM：流道内的蒸汽不能把压力/推力反馈给活塞或曲柄，反之活塞运动也不能扫掠流道（两次流道 run 均以阀室/缸腔的固定几何为边界）。因此流道连通性/死区结论（到达率 0.13–0.33、阀室腔与缸腔远端死区、零穿透）与机构结论（r021 行程 40.000mm、0 干涉）是两个独立验证，不能合并成一个耦合结果。",
  "motionRun": {
    "runId": "r021",
    "cycles": 2,
    "steps": 4000,
    "interferenceEvents": 0,
    "maxJointAnchorDriftMm": 0.0001,
    "strokeMmMeasured": 40.0,
    "valveTravelMmMeasured": 12.0,
    "parts": ["v002","v005","v001","v007","v028","v015","v023","v012","v020","v010","v019"]
  },
  "negativeControls": {
    "rod97mm": {
      "runId": "r005",
      "result": "fail-as-expected",
      "detail": "连杆孔中心距 100→97，按销插孔的真实装配重锚运动副后：上死点邻域 6 次 气缸↔活塞 干涉（t=0.457/0.498/0.539s 与第二圈同相位），峰值 622.8mm³ ≈ 名义 2mm 余隙被 3mm 缩短击穿 1mm。第一次跑（r004）曾得 0 干涉假阴性：原因是运动副锚点仍钉在 97 孔无法到达的设计位置，销-孔错位发生在被运动副豁免的对上——已如实记录并以锚点修正后重跑。几何已恢复（连杆 v023=100）。"
    },
    "intakeWall0p8mm": {
      "version": "v022",
      "result": "flagged-as-expected",
      "detail": "check_printability 报 minWallMm=0.799 @ (57.1,-32.8,123.7)（进汽凸台环壁），witness wallMinMm measured 0.799 / required 1.2，工艺档判定 excluded。几何已恢复（气缸 v028）。"
    },
    "crossheadNoFriction": {
      "result": "no-conclusion-as-expected",
      "detail": "不给 prismatic joint staticFriction 时，工具不输出任何保持力结论（滑块在纯约束下总被视为可滑）——该结果只反映参数缺失，不能当设计结论。补 μ=0.3 后才得到 HOLDS 判定。"
    }
  }
}
